mapper.select:
SELECT p.`id`, p.`task_code`, p.`task_name`, p.`location_name`, p.`call_type`, p.`call_start_time`, p.`call_end_time`, p.`status`, p.`attended_count`, p.`unattended_count`, p.`special_count`, p.`duration`, p.`third_record_id`, p.`deleted`, p.`tenant`, p.`create_by`, p.`create_time`, p.`update_by`, p.`update_time` FROM `person_roll_call_task` p
p.`deleted` = 0
AND p.`call_start_time` >= #{param.callTimePeriod.begin} AND p.`call_end_time` <= #{param.callTimePeriod.end}
AND p.`call_type` = #{param.callType}
AND p.`task_name` = #{param.taskName}
ORDER BY p.`call_start_time` DESC
